<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('administrador');$pageTitle='Usuarios';$action=clean_text($_GET['action']??'list',20);$errors=[];$current=null;$roles=db()->query('SELECT * FROM roles ORDER BY id')->fetchAll();
$load=function(int$id):array{$s=db()->prepare('SELECT u.*,r.nombre role_name FROM usuarios u JOIN roles r ON r.id=u.role_id WHERE u.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Usuario no encontrado.');}return$r;};if(isset($_GET['t'])){$id=decode_id($_GET['t']);if(!$id)abort_forbidden('Token de usuario alterado.');$current=$load($id);}
if(request_is_post()){verify_csrf();$fa=clean_text($_POST['form_action']??'',20);if(in_array($fa,['create','update'],true)){$name=clean_text($_POST['nombre']??'',120);$email=mb_strtolower(clean_text($_POST['email']??'',180));$phone=clean_text($_POST['telefono']??'',30);$company=clean_text($_POST['empresa']??'',150);$role=filter_input(INPUT_POST,'role_id',FILTER_VALIDATE_INT);$status=clean_text($_POST['estado']??'activo',20);$password=(string)($_POST['password']??'');if(mb_strlen($name)<3)$errors[]='Nombre inválido.';if(!valid_email($email))$errors[]='Correo inválido.';if(!$role)$errors[]='Selecciona un rol.';if(!in_array($status,['activo','inactivo','bloqueado'],true))$errors[]='Estado inválido.';$id=$fa==='update'?decode_id($_POST['token_id']??''):null;if($fa==='update'&&!$id)abort_forbidden('Token alterado.');$check=db()->prepare('SELECT id FROM usuarios WHERE email=?'.($id?' AND id<>?':''));$check->execute($id?[$email,$id]:[$email]);if($check->fetch())$errors[]='El correo ya existe.';if($fa==='create'&&strlen($password)<8)$errors[]='La contraseña debe tener al menos 8 caracteres.';if($password!==''&&(strlen($password)<8||!preg_match('/[A-Z]/',$password)||!preg_match('/[a-z]/',$password)||!preg_match('/\d/',$password)))$errors[]='La contraseña debe incluir mayúscula, minúscula y número.';if(!$errors){if($fa==='create'){db()->prepare('INSERT INTO usuarios(role_id,nombre,email,password_hash,telefono,empresa,estado)VALUES(?,?,?,?,?,?,?)')->execute([$role,$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone?:null,$company?:null,$status]);flash('success','Usuario creado.');}else{if($id===(int)user()['id']&&$status!=='activo')$errors[]='No puedes desactivar tu propia cuenta.';if(!$errors){$sql='UPDATE usuarios SET role_id=?,nombre=?,email=?,telefono=?,empresa=?,estado=?,updated_at=NOW()';$params=[$role,$name,$email,$phone?:null,$company?:null,$status];if($password!==''){$sql.=',password_hash=?';$params[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$params[]=$id;db()->prepare($sql)->execute($params);if($id===(int)user()['id']){$_SESSION['user']['nombre']=$name;$_SESSION['user']['email']=$email;}flash('success','Usuario actualizado.');redirect('admin/usuarios.php');}}if(!$errors)redirect('admin/usuarios.php');}preserve_old_input($_POST);$action=$fa==='create'?'new':'edit';}if($fa==='delete'){$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');if($id===(int)user()['id']){flash('danger','No puedes eliminar tu propia cuenta.');redirect('admin/usuarios.php');}db()->prepare('DELETE FROM usuarios WHERE id=?')->execute([$id]);flash('success','Usuario y registros asociados eliminados.');redirect('admin/usuarios.php');}}
if($action==='list')$items=db()->query('SELECT u.*,r.nombre role_name FROM usuarios u JOIN roles r ON r.id=u.role_id ORDER BY u.created_at DESC')->fetchAll();require dirname(__DIR__).'/includes/admin_header.php';
?>
<?php if(in_array($action,['new','edit'],true)):?><div class="panel-heading"><div><h1><?=$action==='new'?'Crear usuario':'Editar usuario'?></h1><p>Administra roles, estado y datos de acceso.</p></div><a class="btn btn-light" href="<?=url('admin/usuarios.php')?>">Cancelar</a></div><form class="form-card" method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="<?=$action==='new'?'create':'update'?>"><?php if($current):?><input type="hidden" name="token_id" value="<?=e(encode_id((int)$current['id']))?>"><?php endif;?><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as$er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><div class="form-grid"><div class="field"><label>Nombre</label><input name="nombre" value="<?=old('nombre',$current['nombre']??'')?>" required></div><div class="field"><label>Correo</label><input type="email" name="email" value="<?=old('email',$current['email']??'')?>" required></div><div class="field"><label>Teléfono</label><input name="telefono" value="<?=old('telefono',$current['telefono']??'')?>"></div><div class="field"><label>Empresa</label><input name="empresa" value="<?=old('empresa',$current['empresa']??'')?>"></div><div class="field"><label>Rol</label><select name="role_id"><?php $sr=(string)($_SESSION['_old']['role_id']??$current['role_id']??2);foreach($roles as$r):?><option value="<?=(int)$r['id']?>" <?=$sr===(string)$r['id']?'selected':''?>><?=e($r['nombre'])?></option><?php endforeach;?></select></div><div class="field"><label>Estado</label><select name="estado"><?php $se=$_SESSION['_old']['estado']??$current['estado']??'activo';foreach(['activo','inactivo','bloqueado']as$st):?><option <?=$se===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select></div><div class="field full"><label>Contraseña <?=$action==='edit'?'(dejar vacía para conservar)':''?></label><input type="password" name="password" <?=$action==='new'?'required':''?>></div></div><button class="btn">Guardar</button></form>
<?php else:?><div class="panel-heading"><div><h1>Usuarios</h1><p>CRUD de administradores y clientes.</p></div><a class="btn" href="<?=url('admin/usuarios.php?action=new')?>">Crear usuario</a></div><div class="table-card"><div class="table-responsive"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Empresa</th><th>Estado</th><th>Registro</th><th>Acciones</th></tr></thead><tbody><?php foreach($items as$it):?><tr><td><?=e($it['nombre'])?></td><td><?=e($it['email'])?></td><td><?=e($it['role_name'])?></td><td><?=e($it['empresa']??'—')?></td><td><span class="badge badge-<?=status_class($it['estado'])?>"><?=e($it['estado'])?></span></td><td><?=format_date($it['created_at'])?></td><td class="table-actions"><a class="btn btn-small btn-light" href="<?=url('admin/usuarios.php?action=edit&t='.encode_id((int)$it['id']))?>">Editar</a><?php if((int)$it['id']!==(int)user()['id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="token_id" value="<?=e(encode_id((int)$it['id']))?>"><button class="btn btn-small btn-danger" data-confirm="¿Eliminar al usuario y todos sus registros?">Eliminar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
<?php clear_old_input();require dirname(__DIR__).'/includes/admin_footer.php';?>
